        self.proc = subprocess.Popen(["./maze_game.sh", str(self.maze_id)], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, bufsize=1)
        self._read_until_prompt()

    def _read_until_prompt(self):
        output = []
        while True:
            line = self.proc.stdout.readline()
            if not line:
                break
            output.append(line)
            if line.strip().startswith(">"):
                break
        return output

    def _send_command(self, cmd):
        self.proc.stdin.write(cmd + "\n")
        self.proc.stdin.flush()
        resp_lines = self._read_until_prompt()
        for line in reversed(resp_lines):
            line = line.strip()
            if line and not line.startswith(">"):
                return line
        return ""

    def move(self, directions):
        cmd = 'move ' + ' & '.join(directions)
        resp = self._send_command(cmd)
        results = [r.strip() for r in resp.split('&')]
        for i, res in enumerate(results):
            d = directions[i]
            dr, dc = DIRS[d]
            nr, nc = self.cur_pos[0] + dr, self.cur_pos[1] + dc
            if res == "moved" or res == "reached exit":
                self.cur_pos = (nr, nc)
                self.min_r = min(self.min_r, nr)
                self.max_r = max(self.max_r, nr)
                self.min_c = min(self.min_c, nc)
                self.max_c = max(self.max_c, nc)
                if res == "reached exit":
                    self.exit_pos = (nr, nc)
            elif res == "hit wall":
                self.maze_map[(nr, nc)] = '#'
        return results

    def explore(self):
        self.maze_map[self.cur_pos] = 'S'
        self.start_pos = self.cur_pos
        self.visited.add(self.cur_pos)
        stack = []
        stack.append((self.cur_pos, iter(DIRS.keys())))
        while stack:
            pos, dirs_iter = stack[-1]
            try:
                d = next(dirs_iter)
            except StopIteration:
                stack.pop()
                if stack:
                    prev_pos, _ = stack[-1]
                    br = self.cur_pos[0] - prev_pos[0]
                    bc = self.cur_pos[1] - prev_pos[1]
                    back_dir = None
                    for dirk, (dr, dc) in DIRS.items():
                        if dr == br and dc == bc:
                            back_dir = dirk
                            break
                    if back_dir:
                        self.move([back_dir])
                continue
            dr, dc = DIRS[d]
            nr, nc = pos[0] + dr, pos[1] + dc
            if (nr, nc) in self.visited or self.maze_map.get((nr, nc)) == '#':
                continue
            res = self.move([d])
            if res[0] == 'hit wall':
                self.maze_map[(nr, nc)] = '#'
                continue
            elif res[0] == 'moved' or res[0] == 'reached exit':
                if (nr, nc) not in self.maze_map:
                    self.maze_map[(nr, nc)] = ' '
                if res[0] == 'reached exit':
                    self.exit_pos = (nr, nc)
                    self.maze_map[(nr, nc)] = 'E'
                self.visited.add((nr, nc))
                stack.append((self.cur_pos, iter(DIRS.keys())))
        while self.cur_pos != self.start_pos:
            br = self.start_pos[0] - self.cur_pos[0]
            bc = self.start_pos[1] - self.cur_pos[1]
            back_dir = None
            for dirk, (dr, dc) in DIRS.items():
                if dr == br and dc == bc:
                    back_dir = dirk
                    break
            if back_dir:
                self.move([back_dir])
            else:
                break

    def save_map(self):
        min_r = min(r for r,c in self.maze_map.keys())
        max_r = max(r for r,c in self.maze_map.keys())
        min_c = min(c for r,c in self.maze_map.keys())
        max_c = max(c for r,c in self.maze_map.keys())
        rows = []
        for r in range(min_r, max_r + 1):
            row_chars = []
            for c in range(min_c, max_c + 1):
                ch = self.maze_map.get((r, c), '#')
                row_chars.append(ch)
            rows.append(''.join(row_chars))
        out_dir = '/app/output'
        if not os.path.exists(out_dir):
            os.makedirs(out_dir)
        fname = os.path.join(out_dir, f'{self.maze_id}.txt')
        with open(fname, 'w') as f:
            for line in rows:
                f.write(line + '\n')

    def close(self):
        try:
            self.proc.stdin.write('exit\n')
            self.proc.stdin.flush()
            self.proc.wait(timeout=2)
        except Exception:
            self.proc.kill()

def main():
    if len(sys.argv) < 2:
        maze_id = 1
    else:
        maze_id = int(sys.argv[1])
    explorer = MazeExplorer(maze_id)
    explorer.explore()
    explorer.save_map()
    explorer.close()

if __name__ == '__main__':
    main()
