        self.proc = subprocess.Popen(["./maze_game.sh", str(self.maze_id)], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, encoding="utf-8", bufsize=1)
        # Consume the welcome lines
        for _ in range(4):
            self.proc.stdout.readline()

        # Initialize start position
        self.grid[self.current_pos] = "S"
        self.visited.add(self.current_pos)

    def update_bounds(self, r, c):
        self.min_r = min(self.min_r, r)
        self.max_r = max(self.max_r, r)
        self.min_c = min(self.min_c, c)
        self.max_c = max(self.max_c, c)

    def send_move(self, directions):
        cmd = "move " + " & ".join(directions) + "\n"
        self.proc.stdin.write(cmd)
        self.proc.stdin.flush()
        response = self.proc.stdout.readline().strip()
        return response.split(" & ")

    def move(self, dir):
        responses = self.send_move([dir])
        assert len(responses) == 1
        resp = responses[0]
        if resp == "hit wall":
            return False
        elif resp == "moved" or resp == "reached exit":
            dr, dc = DIRECTIONS[dir]
            r, c = self.current_pos
            self.current_pos = (r + dr, c + dc)
            self.update_bounds(*self.current_pos)
            if resp == "reached exit":
                self.grid[self.current_pos] = "E"
            else:
                if self.current_pos not in self.grid:
                    self.grid[self.current_pos] = " "
            self.visited.add(self.current_pos)
            return True
        else:
            raise RuntimeError(f"Unexpected response: {resp}")

    def backtrack(self, dir):
        return self.move(OPPOSITE[dir])

    def explore(self):
        r, c = self.current_pos
        for dir, (dr, dc) in DIRECTIONS.items():
            nr, nc = r + dr, c + dc
            if (nr, nc) in self.visited:
                continue
            if self.move(dir):
                self.explore()
                self.backtrack(dir)
            else:
                self.grid[(nr, nc)] = "#"

    def save_map(self):
        rows = self.max_r - self.min_r + 1
        cols = self.max_c - self.min_c + 1
        output_grid = [["#" for _ in range(cols)] for _ in range(rows)]
        for (r, c), ch in self.grid.items():
            rr = r - self.min_r
            cc = c - self.min_c
            output_grid[rr][cc] = ch

        out_dir = "/app/output"
        if not os.path.exists(out_dir):
            os.makedirs(out_dir)
        filename = os.path.join(out_dir, f"{self.maze_id}.txt")
        with open(filename, "w") as f:
            for row in output_grid:
                f.write("".join(row) + "\n")

    def close(self):
        self.proc.stdin.write("exit\n")
        self.proc.stdin.flush()
        self.proc.terminate()


def main():
    if len(sys.argv) < 2:
        maze_id = 1
    else:
        maze_id = int(sys.argv[1])

    explorer = MazeExplorer(maze_id)
    explorer.explore()
    explorer.save_map()
    explorer.close()


if __name__ == "__main__":
    main()
